PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('ADMIN','VENDEDOR','PRODUCAO','FINANCEIRO')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES profiles(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS salespeople(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT DEFAULT '',city TEXT DEFAULT '',commission_type TEXT DEFAULT 'percent',commission_value INTEGER DEFAULT 5,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,legal_name TEXT DEFAULT '',document TEXT DEFAULT '',contact TEXT DEFAULT '',phone TEXT DEFAULT '',email TEXT DEFAULT '',city TEXT NOT NULL,neighborhood TEXT DEFAULT '',state TEXT DEFAULT 'SP',address TEXT DEFAULT '',postal_code TEXT DEFAULT '',segment TEXT DEFAULT 'Outros',origin TEXT DEFAULT 'Outro',notes TEXT DEFAULT '',is_customer INTEGER DEFAULT 0,is_lead INTEGER DEFAULT 1,status TEXT DEFAULT 'Novo lead',salesperson_id TEXT REFERENCES salespeople(id),place_id TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS activities(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),user_id TEXT REFERENCES profiles(id),type TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS followups(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),responsible TEXT NOT NULL DEFAULT '',date TEXT NOT NULL,reason TEXT NOT NULL,done INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,sku TEXT UNIQUE NOT NULL,category TEXT NOT NULL,description TEXT DEFAULT '',price INTEGER NOT NULL CHECK(price>=0),cost INTEGER NOT NULL CHECK(cost>=0),is_plate INTEGER DEFAULT 1,active INTEGER DEFAULT 1,uses_nfc INTEGER DEFAULT 0,uses_acrylic INTEGER DEFAULT 0,controls_stock INTEGER DEFAULT 0,unit TEXT DEFAULT 'un',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT DEFAULT 'un',quantity REAL NOT NULL DEFAULT 0 CHECK(quantity>=0),minimum REAL DEFAULT 10,cost INTEGER DEFAULT 0,supplier TEXT DEFAULT '',updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_components(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),inventory_id TEXT NOT NULL REFERENCES inventory_items(id),quantity REAL NOT NULL CHECK(quantity>0),UNIQUE(product_id,inventory_id));
CREATE TABLE IF NOT EXISTS sales(id TEXT PRIMARY KEY,number INTEGER NOT NULL UNIQUE,company_id TEXT NOT NULL REFERENCES companies(id),salesperson_id TEXT REFERENCES salespeople(id),date TEXT NOT NULL,total INTEGER NOT NULL,cost INTEGER NOT NULL,profit INTEGER NOT NULL,plates INTEGER NOT NULL,commission INTEGER DEFAULT 0,commission_rule TEXT NOT NULL,margin REAL NOT NULL DEFAULT 0,method TEXT NOT NULL,due_date TEXT NOT NULL,notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sale_items(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),product_id TEXT NOT NULL REFERENCES products(id),product_name TEXT NOT NULL,quantity INTEGER NOT NULL,price INTEGER NOT NULL,cost INTEGER NOT NULL,is_plate INTEGER NOT NULL,components_snapshot TEXT NOT NULL DEFAULT '[]',margin REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL,date TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL UNIQUE REFERENCES sales(id),status TEXT DEFAULT 'Pedido recebido',promised_date TEXT,notes TEXT DEFAULT '',produced_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,inventory_id TEXT NOT NULL REFERENCES inventory_items(id),quantity REAL NOT NULL,type TEXT NOT NULL,description TEXT NOT NULL,order_id TEXT REFERENCES orders(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchases(id TEXT PRIMARY KEY,inventory_id TEXT NOT NULL REFERENCES inventory_items(id),supplier TEXT NOT NULL,quantity REAL NOT NULL,total INTEGER NOT NULL,date TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY,description TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),date TEXT NOT NULL,paid INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS goals(id TEXT PRIMARY KEY,period TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE IF NOT EXISTS routes(id TEXT PRIMARY KEY,name TEXT NOT NULL,date TEXT NOT NULL,salesperson_id TEXT REFERENCES salespeople(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS route_stops(id TEXT PRIMARY KEY,route_id TEXT NOT NULL REFERENCES routes(id),company_id TEXT NOT NULL REFERENCES companies(id),position INTEGER NOT NULL,status TEXT DEFAULT 'Pendente',UNIQUE(route_id,company_id));
CREATE TABLE IF NOT EXISTS ranking_checks(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),term TEXT NOT NULL,location TEXT NOT NULL,position INTEGER,date TEXT NOT NULL,source TEXT NOT NULL,notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),sale_id TEXT REFERENCES sales(id),order_id TEXT REFERENCES orders(id),storage_path TEXT NOT NULL,name TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,user_id TEXT REFERENCES profiles(id),action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(date);
CREATE INDEX IF NOT EXISTS idx_activities_company ON activities(company_id);
INSERT OR IGNORE INTO migrations(version) VALUES(1);
